  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 1)).toThrow(
      "not in the cart",
    );
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart should be unaffected
    expect(cart.totals().subtotalCents).toBe(1000);
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents × quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 3); // 6000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(8000);
  });

  it("defaults to no discount, no tax, free shipping", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("applies discount policy and clamps discount to [0, subtotal]", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
    });
    cart.add(productA, 1); // subtotal 1000, discount 500
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(totals.totalCents).toBe(500);
  });

  it("clamps discount that exceeds subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(5000),
    });
    cart.add(productA, 1); // subtotal 1000, discount clamped to 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("computes tax on the discounted subtotal, not the original", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50),
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(productA, 1); // subtotal 1000, discount 500, tax 10% of 500 = 50
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(500);
    expect(totals.taxCents).toBe(50);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const shippingCalc: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(799),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      shippingCalculator: shippingCalc,
    });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
    cart.totals();
    expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("full pipeline: subtotal → discount → tax → shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 5); // subtotal 5000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(500); // 10% of 5000
    const discounted = 4500;
    expect(totals.taxCents).toBe(Math.floor(discounted * 0.08)); // 360
    expect(totals.shippingCents).toBe(500);
    expect(totals.totalCents).toBe(discounted + 360 + 500);
  });

  it("empty cart totals are all zeros", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50),
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      shippingCalculator: new FlatShippingCalculator(500),
    });
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart — async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 2); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    // Updated price: 1500 × 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("throws InventoryError when inventory check denies", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes inventory check when available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes inventory check when availableQuantity is not provided", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal 10000, discount 1000, discounted 9000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // 8.75% of 9000 = 787.5 → 787
    expect(result.totals.taxCents).toBe(787);
    expect(result.totals.discountCents).toBe(1000);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1200) // a: 1200
        .mockResolvedValueOnce(2500), // b: 2500
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    // no discount → taxable = 4900, tax = 490
    expect(result.totals.taxCents).toBe(490);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(4900 + 490 + 500);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price api down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price api down",
    );
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "discontinued",
        }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 for subtotal %i",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("floors fractional cents (10% of 999 = 99.9 → 99)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("100% gives full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% gives 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotal without overflow", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(50_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns full amount when subtotal exceeds discount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1500);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns exact subtotal when discount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      // Both compute against 10000: 1000 + 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -500 clamped to 0, + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("compounds discounts sequentially", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000 → remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900 → remaining 8100
        ],
        "chain",
      );
      // total discount = 1000 + 900 = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const pctFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      const fixedFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // pctFirst: 50% of 1000 = 500, then min(200, 500) = 200 → 700
      // fixedFirst: min(200, 1000) = 200, then 50% of 800 = 400 → 600
      expect(pctFirst.computeDiscountCents(1000)).toBe(700);
      expect(fixedFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("stops reducing once remaining is zero", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed takes all 500, remaining is 0, pct gets 0
      expect(composite.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

