describe("refreshPrices", () => {
  const mkLines = (): CartLine[] => [
    { product: { id: "a", name: "Widget A", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "Widget B", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates unitPriceCents from the fetcher", async () => {
