    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("computes tax on the discounted subtotal, not the original", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50),
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(productA, 1); // subtotal 1000, discount 500, tax 10% of 500 = 50
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(500);
    expect(totals.taxCents).toBe(50);
