describe("Cart — async checkout()", () => {
  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 2); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    // Updated price: 1500 × 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("works without any collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("throws InventoryError when inventory check denies", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes inventory check when available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes inventory check when availableQuantity is not provided", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal 10000, discount 1000, discounted 9000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    // 8.75% of 9000 = 787.5 → 787
    expect(result.totals.taxCents).toBe(787);
    expect(result.totals.discountCents).toBe(1000);
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1200) // a: 1200
        .mockResolvedValueOnce(2500), // b: 2500
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal: 1200*2 + 2500*1 = 4900
    expect(result.totals.subtotalCents).toBe(4900);
    // no discount → taxable = 4900, tax = 490
    expect(result.totals.taxCents).toBe(490);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(4900 + 490 + 500);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price api down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price api down",
    );
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({
          available: false,
          reason: "discontinued",
        }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});
